def transform(grid):
    h, w = len(grid), len(grid[0])
    row_stripes = all(len(set(row)) == 1 for row in grid)
    if row_stripes:
        known = [(r, grid[r][0]) for r in range(h) if grid[r][0] != 0]
        for p in range(1, h + 1):
            phase = {}
            valid = True
            for r, color in known:
                k = r % p
                if k in phase and phase[k] != color:
                    valid = False
                    break
                phase[k] = color
            if valid and len(phase) == p:
                break
        return [[phase[r % p] for _ in range(w)] for r in range(h)]
    known = [(r - c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    for p in range(1, h + w):
        phase = {}
        valid = True
        for k, color in known:
            residue = k % p
            if residue in phase and phase[residue] != color:
                valid = False
                break
            phase[residue] = color
        if valid and len(phase) == p:
            break
    return [[phase[(r - c) % p] for c in range(w)] for r in range(h)]

